// ============================================================
//  discord-connect-callback.js — Discord redirects here after someone
//  authorizes adding the RaidLead bot to a server ("Connect to Discord").
//
//  No RaidLead session is required to complete this: the `state` token
//  (generated by guild.js's beginDiscordConnect) identifies which team the
//  connection is for, so the person who actually has "Manage Server" on the
//  Discord side doesn't need a RaidLead login -- useful when they're not the
//  same person as the RaidLead officer who started the connection.
//
//  Any number of teams can independently link the same Discord server --
//  there's no uniqueness constraint on discord_guild_id, since two teams
//  under the same (or different) guilds sharing a Discord server is a
//  perfectly normal setup, not a conflict.
// ============================================================
const { createClient } = require('@supabase/supabase-js');
const { setCommonHeaders } = require('./lib/session');

module.exports = async (req, res) => {
  setCommonHeaders(res);

  const discordGuildId = req.query.guild_id;
  const state = req.query.state;

  if (!discordGuildId || !state) {
    return res.redirect(302, '/?discord_connect_error=' + encodeURIComponent('Discord did not return the expected information. Please try connecting again from RaidLead.'));
  }

  const supabase = createClient(process.env.SUPABASE_URL, process.env.SUPABASE_SERVICE_KEY);
  try {
    const { data: teamRow } = await supabase
      .from('teams')
      .select('id, discord_connect_state_expires_at')
      .eq('discord_connect_state', state)
      .maybeSingle();

    if (!teamRow) {
      return res.redirect(302, '/?discord_connect_error=' + encodeURIComponent('This connection link is invalid or was already used. Please start over in RaidLead.'));
    }
    if (teamRow.discord_connect_state_expires_at && new Date(teamRow.discord_connect_state_expires_at) < new Date()) {
      return res.redirect(302, '/?discord_connect_error=' + encodeURIComponent('This connection link expired. Please start over in RaidLead.'));
    }

    const { error } = await supabase.from('teams').update({
      discord_guild_id: discordGuildId,
      discord_connect_state: null,
      discord_connect_state_expires_at: null,
    }).eq('id', teamRow.id);
    if (error) throw error;

    return res.redirect(302, '/?discord_connected=1');
  } catch (err) {
    return res.redirect(302, '/?discord_connect_error=' + encodeURIComponent(err.message));
  }
};
